import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, vec3, vec4, mix, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color, DirectionalLight, AmbientLight } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 1, hex: '#14141a' },
    ],
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItems = items.filter((i) => i.role === 'caption');

  const group = new Group();
  const timelines = [];
  const disposables = [];
  const primitiveHandles = [];

  // ---- STAGE BACKDROP (vertical gradient) ----
  const stops = colors.gradientStops ?? [
    { at: 0, hex: colors.background },
    { at: 1, hex: colors.surface },
  ];
  const cTop = new Color(stops[stops.length - 1].hex);
  const cBot = new Color(stops[0].hex);

  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = mix(
    vec3(cBot.r, cBot.g, cBot.b),
    vec3(cTop.r, cTop.g, cTop.b),
    uv().y
  );
  const bgGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---- LIGHTS (node-local rim + ambient fill) ----
  const ambient = new AmbientLight(0xffffff, 0.5);
  group.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(-2.5, 3, 4);
  group.add(key);

  const rim = new DirectionalLight(new Color(colors.accent).getHex(), 0.8);
  rim.position.set(3, -1, 2);
  group.add(rim);

  // ---- IMAGE COLUMN ----
  const inkColor = new Color(colors.ink);
  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);

  const PLATE_W = 1.9;
  const PLATE_H = 1.2;
  const PITCH = 1.5;
  const COL_X = 0.9;
  const LOOP = 9.0;
  const COUNT = 6;

  const column = new Group();
  column.position.x = COL_X;
  group.add(column);

  const plateMats = [];
  const plateGeos = [];
  const plateMeshes = [];

  // distinct filmic tints per plate so none read as void before texture loads
  const tints = [
    new Color('#2a2320'),
    new Color('#232a2a'),
    new Color('#2a2528'),
    new Color('#252a24'),
    new Color('#282a2c'),
    new Color('#2c2726'),
  ];

  const captionMeshes = [];

  for (let i = 0; i < COUNT; i++) {
    const plateGroup = new Group();
    plateGroup.position.set(0, i * PITCH, 0);
    plateGroup.userData.baseIndex = i;

    // bevel frame (machined ink, brushed edge)
    const frameGeo = new BoxGeometry(PLATE_W + 0.06, PLATE_H + 0.06, 0.05);
    const frameMat = new MeshStandardNodeMaterial();
    frameMat.color = inkColor.clone();
    frameMat.roughness = 0.5;
    frameMat.metalness = 0.5;
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.02;
    plateGroup.add(frame);
    disposables.push(frameGeo, frameMat);

    // photo plate
    const plateMat = new MeshStandardNodeMaterial();
    plateMat.color = tints[i].clone();
    plateMat.roughness = 0.6;
    plateMat.metalness = 0.1;
    plateMat.clearcoat = 0.1;
    const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H);
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.z = 0.01;
    plateGroup.add(plate);
    plateMats.push(plateMat);
    plateGeos.push(plateGeo);
    disposables.push(plateGeo, plateMat);

    // accent strip on left edge (hidden until focused)
    const stripGeo = new PlaneGeometry(0.03, PLATE_H);
    const stripMat = new MeshBasicNodeMaterial();
    stripMat.color = accentColor.clone();
    stripMat.transparent = true;
    stripMat.opacity = 0;
    const strip = new Mesh(stripGeo, stripMat);
    strip.position.set(-PLATE_W / 2 - 0.02, 0, 0.03);
    plateGroup.add(strip);
    plateGroup.userData.strip = strip;
    disposables.push(stripGeo, stripMat);

    // caption
    const capText = captionItems[i]?.text ?? `PLATE ${i + 1}`;
    const cap = ctx.fontAtlas.createText(capText, {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'right',
      letterSpacingPx: 2,
    });
    cap.scale.setScalar(0.9);
    cap.position.set(-1.6 - COL_X, 0, 0.02);
    cap.visible = false;
    plateGroup.add(cap);
    plateGroup.userData.caption = cap;
    captionMeshes.push(cap);

    column.add(plateGroup);
    plateMeshes.push(plateGroup);
  }

  // load base texture into all plates
  if (config.imageUrl || config.intent?.visualSpec) {
    const url = config.imageUrl ?? '/prism-mock/home/nodes/feature-card.png';
    ctx.textureLoader.loadTexture(url).then((tex) => {
      plateMats.forEach((m, idx) => {
        m.map = tex;
        // keep distinct tint blend by leaving color tinted lightly
        m.color = new Color('#ffffff').lerp(tints[idx], 0.18);
        m.needsUpdate = true;
      });
    }).catch(() => {});
  }

  // ---- HEADLINE ----
  if (headlineItem) {
    const headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: 68,
      color: '#e8ecf2',
      align: 'left',
    });
    headline.position.set(-1.6, 1.9, 0.1);
    group.add(headline);
    group.userData.headline = headline;
  }

  // ---- FOCUS / SCROLL STATE ----
  const state = { scroll: 0, vel: 0, y: 0 };

  function updateColumn() {
    column.position.y = state.y;
    // focus nearest plate to y=0 (world) considering loop
    let bestDist = Infinity;
    let best = null;
    for (const pg of plateMeshes) {
      // effective world y within loop
      let wy = ((pg.userData.baseIndex * PITCH + state.y) % LOOP + LOOP) % LOOP;
      if (wy > LOOP / 2) wy -= LOOP;
      pg.position.y = pg.userData.baseIndex * PITCH; // keep base, column moves
      const d = Math.abs(wy);
      const focus = Math.max(0, 1 - d / (PITCH * 0.6));
      const scale = 1.0 + 0.06 * focus;
      pg.scale.setScalar(scale);
      pg.userData.strip.material.opacity = focus;
      pg.userData.caption.visible = focus > 0.25;
      pg.userData.caption.material && (pg.userData.caption.material.opacity = focus);
      if (d < bestDist) {
        bestDist = d;
        best = pg;
      }
    }
  }

  updateColumn();

  // ---- ENTRANCE (weighted-settle) ----
  group.scale.setScalar(0.98);
  const introTl = gsap.timeline();
  introTl.fromTo(
    column.position,
    { y: -0.4 },
    { y: 0, duration: 0.8, ease: 'power3.out', onUpdate: () => { state.y = column.position.y; updateColumn(); } }
  );
  introTl.fromTo(
    group.scale,
    { x: 0.98, y: 0.98, z: 0.98 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0
  );
  timelines.push(introTl);

  // ---- IDLE breathing (single slow transform) ----
  const idleTl = gsap.to(column.position, {
    y: '+=0.05',
    duration: 4,
    ease: 'sine.inOut',
    repeat: -1,
    yoyo: true,
    onUpdate: () => { state.y = column.position.y; updateColumn(); },
  });
  timelines.push(idleTl);

  // ---- CINEMATIC PRIMITIVES ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const handle = fn(group, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- SCROLL HANDLER (weighted inertia + settle) ----
  let settleTl = null;
  group.userData.handlers = {
    scroll: (payload) => {
      const delta = (payload?.delta ?? payload?.deltaY ?? 0) * 0.0015;
      state.vel += delta;
      if (settleTl) settleTl.kill();
      const target = state.y - state.vel * PITCH;
      settleTl = gsap.to(state, {
        y: target,
        vel: 0,
        duration: 0.9,
        ease: 'power4.out',
        onUpdate: updateColumn,
      });
      timelines.push(settleTl);
    },
  };

  // ---- CLEANUP ----
  group.userData.cleanup = () => {
    timelines.forEach((t) => t && t.kill());
    if (settleTl) settleTl.kill();
    primitiveHandles.forEach((h) => h && h.cleanup && h.cleanup());
    disposables.forEach((d) => d && d.dispose && d.dispose());
    group.traverse((o) => {
      if (o.geometry && o.geometry.dispose) o.geometry.dispose();
      if (o.material) {
        if (o.material.map && o.material.map.dispose) o.material.map.dispose();
        if (o.material.dispose) o.material.dispose();
      }
    });
  };

  return group;
}
